CREATE TABLE notification_templates (id CHAR(36) PRIMARY KEY,tenant_id VARCHAR(191) NOT NULL,code VARCHAR(191) NOT NULL,channel VARCHAR(32) NOT NULL,locale VARCHAR(32) NOT NULL,subject TEXT NOT NULL,content TEXT NOT NULL,status VARCHAR(32) NOT NULL,version BIGINT NOT NULL DEFAULT 1,created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,created_by TEXT NOT NULL,updated_by TEXT NOT NULL,UNIQUE KEY notification_template_uq(tenant_id,code,channel,locale)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE notification_deliveries (id CHAR(36) PRIMARY KEY,tenant_id VARCHAR(191) NOT NULL,template_code VARCHAR(191) NOT NULL,channel VARCHAR(32) NOT NULL,locale VARCHAR(32) NOT NULL,recipient TEXT NOT NULL,variables JSON NOT NULL,idempotency_key VARCHAR(191) NOT NULL,status VARCHAR(32) NOT NULL,provider VARCHAR(191) NOT NULL DEFAULT '',provider_message_id TEXT NOT NULL,failure_reason TEXT NOT NULL,attempts INT NOT NULL DEFAULT 0,next_attempt_at DATETIME(6) NOT NULL,version BIGINT NOT NULL DEFAULT 1,created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,created_by TEXT NOT NULL,updated_by TEXT NOT NULL,UNIQUE KEY notification_delivery_key_uq(tenant_id,idempotency_key),INDEX notification_deliveries_dispatch_idx(status,next_attempt_at,created_at),INDEX notification_deliveries_tenant_idx(tenant_id,created_at DESC,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
